import pandas as pd
import numpy as np
from collections import defaultdict

DATASET_PATH = 'chunks_csv/cyclehire_w002.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# Load data
df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

# Compute self_containment_ratio
departures = df.groupby('StartBorough').size()
self_contained = df.groupby('StartBorough').apply(lambda x: (x['StartBorough'] == x['EndBorough']).sum())
self_containment_ratio = (self_contained / departures).to_dict()

boroughs = list(self_containment_ratio.keys())

# Build adjacency list
borough_neighbors = defaultdict(set)
for _, row in adj_df.iterrows():
    b = row['borough']
    n = row['neighbor']
    borough_neighbors[b].add(n)
    borough_neighbors[n].add(b)

# Compute neighbor_avg for each borough
neighbor_avg = {}
for b in boroughs:
    neighbors = borough_neighbors[b]
    neighbor_ratios = [self_containment_ratio[n] for n in neighbors if n in self_containment_ratio]
    if neighbor_ratios:
        neighbor_avg[b] = np.mean(neighbor_ratios)
    else:
        neighbor_avg[b] = np.nan  # No neighbors

# Compute overall mean
overall_mean = np.mean(list(self_containment_ratio.values()))

# Compute observed local statistics (product of (self_ratio - mean) and (neighbor_avg - mean))
observed_local_stats = {}
for b in boroughs:
    if b in neighbor_avg and not np.isnan(neighbor_avg[b]):
        self_diff = self_containment_ratio[b] - overall_mean
        neighbor_diff = neighbor_avg[b] - overall_mean
        local_stat = self_diff * neighbor_diff
        observed_local_stats[b] = local_stat
    else:
        observed_local_stats[b] = np.nan

# Perform permutations
num_permutations = 500
permuted_local_stats = {b: [] for b in boroughs}

for _ in range(num_permutations):
    # Shuffle the self_containment_ratio
    shuffled_ratios = {b: r for b, r in zip(boroughs, np.random.permutation(list(self_containment_ratio.values())))}

    # Compute neighbor_avg for shuffled ratios
    permuted_neighbor_avg = {}
    for b in boroughs:
        neighbors = borough_neighbors[b]
        neighbor_ratios = [shuffled_ratios[n] for n in neighbors if n in shuffled_ratios]
        if neighbor_ratios:
            permuted_neighbor_avg[b] = np.mean(neighbor_ratios)
        else:
            permuted_neighbor_avg[b] = np.nan

    # Compute local stats for this permutation
    for b in boroughs:
        if b in permuted_neighbor_avg and not np.isnan(permuted_neighbor_avg[b]):
            self_diff = shuffled_ratios[b] - overall_mean
            neighbor_diff = permuted_neighbor_avg[b] - overall_mean
            local_stat = self_diff * neighbor_diff
            permuted_local_stats[b].append(local_stat)
        else:
            permuted_local_stats[b].append(np.nan)

# Compute p-values for each borough
p_values = {}
for b in boroughs:
    observed = observed_local_stats[b]
    if np.isnan(observed):
        p_values[b] = np.nan
        continue
    permuted = np.array(permuted_local_stats[b])
    permuted = permuted[~np.isnan(permuted)]
    if len(permuted) == 0:
        p_values[b] = np.nan
        continue
    if observed > 0:
        count = np.sum(permuted >= observed)
        p = (count + 1) / (len(permuted) + 1)
    else:
        count = np.sum(permuted <= observed)
        p = (count + 1) / (len(permuted) + 1)
    p_values[b] = p

# Identify significant hot and cold spots
significant_boroughs = []
for b in boroughs:
    p = p_values[b]
    if np.isnan(p):
        continue
    observed_stat = observed_local_stats[b]
    if observed_stat > 0 and p < 0.05:
        self_ratio = self_containment_ratio[b]
        neighbor_avg_b = neighbor_avg[b]
        if self_ratio > overall_mean and neighbor_avg_b > overall_mean:
            significant_boroughs.append((b, 'HH', self_ratio, p))
        elif self_ratio < overall_mean and neighbor_avg_b < overall_mean:
            significant_boroughs.append((b, 'LL', self_ratio, p))

# Format final answer
final_answer = []
for b, type_, ratio, p in significant_boroughs:
    final_answer.append(f"{b} ({type_}, statistical method={p:.4f})")
if final_answer:
    print(f"FINAL ANSWER: {', '.join(final_answer)}")
else:
    print("FINAL ANSWER: none")
